package com.garmentstore.auth.dto;
import jakarta.validation.constraints.*;
public record RegisterRequest(@NotBlank(message="Name is required") @Size(min=2,max=150,message="Name must be between 2 and 150 characters") String name, @Email(message="Email must be valid") @Size(max=180,message="Email must not exceed 180 characters") String email, @Pattern(regexp="^[6-9][0-9]{9}$",message="Mobile must be a valid 10 digit Indian mobile number") String mobile, @NotBlank(message="Password is required") @Size(min=8,max=72,message="Password must be between 8 and 72 characters") @Pattern(regexp="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z0-9]).*$",message="Password must contain uppercase, lowercase, number and special character") String password){ @AssertTrue(message="Either email or mobile is required") public boolean isEmailOrMobilePresent(){return (email!=null&&!email.isBlank())||(mobile!=null&&!mobile.isBlank());}}
